client_script:
frappe.web_form.after_save = () => {
    // Retrieve form values
    const num_adults = frappe.web_form.get_value('num_adults');
    const num_children = frappe.web_form.get_value('num_children');
    const num_infants = frappe.web_form.get_value('num_infants');
    const arrival_month = frappe.web_form.get_value('arrival_month');
    const num_nights = frappe.web_form.get_value('num_nights');
    const weekend = frappe.web_form.get_value('weekend');
    const holiday = frappe.web_form.get_value('holiday');
    const customer_origin = frappe.web_form.get_value('customer_origin');
    const hotel_name = frappe.web_form.get_value('hotel_name');
    // Call the server-side function
    frappe.call({
        method: 'hotel_recommendation_system.api.submit_user_info',
        args: {
            num_adults: num_adults, 
            num_children: num_children,
            num_infants: num_infants, 
            arrival_month: arrival_month, 
            num_nights: num_nights,
            weekend: weekend, 
            holiday: holiday,
            customer_origin: customer_origin, 
            hotel_name: hotel_name
        },
        callback: (response) => {
            // Process the response
            const bundles = response.message;

            // Encode the bundles data as a JSON string for the URL
            const encodedBundles = encodeURIComponent(JSON.stringify(bundles));
            console.log(response.message);
            // Redirect to the /packages page with the bundles data
            window.location.href = `/packages?bundles=${encodedBundles}`;
        }
    });

};
